{
  "name": "通用实验仪器控制模块",
  "name_en": "Generic Laboratory Instrument Control Module",
  "manufacturer": "",
  "description": "这是一个面向实验室数据采集与运动控制系统的通用控制模块，用于统一管理探测器和执行器类仪器的初始化、采集触发、停止、数据保存和状态更新。根据现有证据，它并不对应某一特定物理仪器，而是用于实验自动化平台中的通用仪器控制组件。",
  "description_en": "This is a generic control module for laboratory data acquisition and motion-control systems. It is used to manage detector- and actuator-type instruments, including hardware initialization, acquisition triggering, stopping, data saving, and status updates. Based on the available evidence, it does not correspond to a single specific physical instrument, but rather to a general instrument-control component used in lab automation.",
  "tag_hints": [
    "data acquisition control",
    "detector readout",
    "actuator control",
    "instrument initialization",
    "HDF5 data saving",
    "lab automation",
    "status monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-create_new_file",
      "description": "创建新的数据文件。",
      "description_en": "Create a new data file."
    },
    {
      "action_name": "auto-h5saver",
      "description": "获取或设置 HDF5 数据保存器。",
      "description_en": "Get or set the HDF5 data saver."
    },
    {
      "action_name": "auto-close_file",
      "description": "关闭当前数据文件。",
      "description_en": "Close the current data file."
    },
    {
      "action_name": "auto-module_and_data_saver",
      "description": "获取或设置模块与数据保存器。",
      "description_en": "Get or set the module and data saver."
    },
    {
      "action_name": "auto-custom_command",
      "description": "发送自定义控制命令。",
      "description_en": "Send a custom control command."
    },
    {
      "action_name": "auto-thread_status",
      "description": "处理并转发来自硬件线程的状态信息。",
      "description_en": "Process and forward status information from the hardware thread."
    },
    {
      "action_name": "auto-grab",
      "description": "启动数据采集，或读取执行器当前值。",
      "description_en": "Start data acquisition or read the current actuator value."
    },
    {
      "action_name": "auto-stop_grab",
      "description": "停止数据采集或当前值轮询。",
      "description_en": "Stop data acquisition or current-value polling."
    },
    {
      "action_name": "auto-append_data",
      "description": "追加数据。",
      "description_en": "Append data."
    },
    {
      "action_name": "auto-insert_data",
      "description": "插入数据。",
      "description_en": "Insert data."
    },
    {
      "action_name": "auto-quit_fun",
      "description": "退出控制模块。",
      "description_en": "Quit the control module."
    },
    {
      "action_name": "auto-init_hardware",
      "description": "初始化或取消初始化硬件。",
      "description_en": "Initialize or deinitialize the hardware."
    },
    {
      "action_name": "auto-init_hardware_ui",
      "description": "通过界面初始化或取消初始化硬件。",
      "description_en": "Initialize or deinitialize the hardware through the user interface."
    },
    {
      "action_name": "auto-show_log",
      "description": "显示日志文件。",
      "description_en": "Show the log file."
    },
    {
      "action_name": "auto-show_config",
      "description": "显示当前配置。",
      "description_en": "Show the current configuration."
    },
    {
      "action_name": "auto-update_status",
      "description": "更新状态信息。",
      "description_en": "Update the status message."
    },
    {
      "action_name": "auto-manage_ui_actions",
      "description": "管理界面动作的属性状态。",
      "description_en": "Manage the attribute state of UI actions."
    }
  ]
}

